/*
 * A045007  Numbers whose base-3 representation contains exactly three 0's and
 *          three 2's.
 * https://oeis.org/A045007
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the n-th integer whose base‑3 representation contains *
 *            exactly three 0's and three 2's (any number of 1's may appear).
 *            * The sequence is generated by enumerating all integers and
 *            selecting * those whose base‑3 digits contain exactly three
 *            zeros and three twos
 * Range:     u8 none, u16 n <= 1560, u32 n <= 1560, u64 n <= 1560,
 *            u128 n <= 1560, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* Return the n-th member of OEIS sequence A045007.  The function
 * retains a cache of all terms found so far, so repeated calls with
 * arbitrary indices are efficient. */
seq_t a(idx_t n)
{
    static seq_t *cache = NULL;      /* cached terms                */
    static size_t cache_cap = 0;     /* allocated cache capacity    */
    static size_t cache_len = 0;     /* number of terms cached      */
    static idx_t next_len = 5;       /* next base‑3 length to process
                                        (next_len+1 = actual digit count) */

    /* Pre‑compute powers of 3 up to 3^31 (< 2^64).  All required lengths
     * for n up to ~10000 lie well below this limit. */
    static bool pow3_init = false;
    static uint64_t pow3[32];
    if (!pow3_init) {
        pow3[0] = 1;
        for (int i = 1; i < 32; ++i)
            pow3[i] = pow3[i-1] * 3ULL;
        pow3_init = true;
    }

    /* Generate terms until the cache contains at least n elements. */
    while (cache_len < (size_t)n) {
        /* Process all integers whose base‑3 representation has
         * length L = next_len+1.  We advance to the next length after
         * studying the entire interval for the current length. */
        idx_t L = ++next_len;
        if (L >= 32)   /* safety guard: should never happen for n ≤ 10000 */
            return 0;

        uint64_t start = pow3[L-1];  /* smallest L‑digit base‑3 number */
        uint64_t end   = pow3[L] - 1;/* largest L‑digit base‑3 number  */

        for (uint64_t x = start; x <= end; ++x) {
            /* Count zeros and twos in the base‑3 representation of x. */
            uint64_t y = x;
            int cnt0 = 0, cnt2 = 0;
            while (y) {
                int d = y % 3;
                if (d == 0) ++cnt0;
                else if (d == 2) ++cnt2;
                y /= 3;
            }
            if (cnt0 == 3 && cnt2 == 3) {
                /* Ensure the cache has space for another term. */
                if (cache_len == cache_cap) {
                    size_t new_cap = cache_cap ? cache_cap * 2 : 64;
                    seq_t *tmp = (seq_t *)realloc(cache,
                                                  new_cap * sizeof(seq_t));
                    if (!tmp)  /* allocation failure – return 0 as sentinel */
                        return 0;
                    cache = tmp;
                    cache_cap = new_cap;
                }
                cache[cache_len++] = (seq_t)x;
            }
        }
        /* After finishing this length, the loop will either terminate
         * (if cache_len >= n) or continue with the next length. */
    }

    return cache[(size_t)n - 1];
}
